function safeInit(label, fn) {
try { fn(); } catch (e) { if (window.console) console.error("main.js: " + label + " failed", e); }
}
document.addEventListener("DOMContentLoaded", () => {
safeInit("Localization.init", () => {
if (window.Localization) Localization.init();
});
safeInit("I18N.init", () => { if (window.I18N) I18N.init(); });
safeInit("SEO.initGlobal", () => { if (window.SEO) SEO.initGlobal(); });
safeInit("Analytics.init", () => { if (window.Analytics) Analytics.init(); });
safeInit("UI.init", () => { if (window.UI) UI.init(); });
safeInit("Catalog", () => {
if (!window.Catalog) return;
if (document.getElementById("catalogGrid")) Catalog.init();
if (document.getElementById("collectionDetail")) Catalog.initDetail();
if (document.getElementById("leagueDetail")) Catalog.initLeaguePage();
if (document.getElementById("regionDetail")) Catalog.initRegionPage();
if (document.getElementById("clubDetail")) Catalog.initClubPage();
if (document.getElementById("jerseyDetail")) Catalog.initJerseyPage();
if (document.getElementById("filterControls")) Catalog.initCatalogPage();
if (document.getElementById("reviewsPage")) Catalog.initReviewsPage();
if (document.getElementById("searchInput")) Catalog.initSiteSearch();
});
});
